mapper.update:
update post_comment_reply
set status = #{status}
where comment_id = #{commentId}

mapper.select:
SELECT comment_id, COUNT(*) as `count` FROM comment_like WHERE comment_id IN
#{commentId}
GROUP BY comment_id

SELECT comment_id, COUNT(*) as `count` FROM post_comment_reply WHERE comment_id IN
#{commentId}
GROUP BY comment_id

SELECT reply_id, comment_id, from_user_id, to_user_id, parent_reply_id, content, status, create_time FROM (
SELECT r.*,
ROW_NUMBER() OVER (
    PARTITION BY r.comment_id
    ORDER BY r.create_time DESC
) AS rn
FROM post_comment_reply r
WHERE r.comment_id IN

    #{commentId}

AND r.status = 0
) t
WHERE t.rn  <=  #{limit}
ORDER BY t.comment_id, t.create_time DESC

SELECT reply_id, COUNT(*) as `count` FROM reply_like WHERE reply_id IN
#{replyId}
GROUP BY reply_id
